func keys(fs []Finding) []key {
	out := make([]key, 0, len(fs))
	for _, f := range fs {
		out = append(out, key{f.File, f.Check, f.Line})
	}
	return out
}

func only(fs []Finding, check string) []int {
	var lines []int
	for _, f := range fs {
		if f.Check == check {
			lines = append(lines, f.Line)
		}
	}
	return lines
}

