func TestLongRunningProgram(t *testing.T) {
	// 10 * 10 * 10 itérations imbriquées : exécution plus longue, doit rester rapide.
	out, err := Run("++++++++++[>++++++++++[>++++++++++[>+<-]<-]<-]>>>.", nil, limit)
	if err != nil || !bytes.Equal(out, []byte{232}) { // 1000 mod 256 = 232
